/**
 * Kore.ai authentication — API-key (JWT) model.
 *
 * Kore.ai contact-center APIs are authenticated by a JWT token generated
 * client-side from a Client ID + Client Secret pair using HS256, plus an
 * Account ID passed as a separate header.  We treat the pre-generated JWT as
 * the "api_key" that the operator pastes into the credential form; no OAuth
 * redirect is involved.
 *
 * Required credential fields:
 *   • jwt       — short-lived JWT token (re-generated by the operator as needed)
 *   • accountId — the Kore.ai Account ID shown on the App Credentials page
 *   • streamId  — the Bot / Stream ID (used in every API path)
 *   • host      — (optional) self-hosted / EU environment base URL
 */
import type { Credentials, CredentialField } from '@opensteward/shared'
import { DEFAULT_HOST } from './constants'

export function getAuthUrlUnsupported(): never {
  throw new Error('kore-ai uses static JWT auth; use credentialFields() instead')
}

export function credentialFields(): CredentialField[] {
  return [
    {
      name: 'jwt',
      label: 'JWT Token',
      type: 'password',
      required: true,
      helpText:
        'A JWT (HS256) signed with your Kore.ai app Client Secret. ' +
        'Generate it at https://developer.kore.ai/tools/jwt/ using your Client ID as the appId claim.',
    },
    {
      name: 'accountId',
      label: 'Account ID',
      type: 'text',
      required: true,
      helpText: 'Found on the App Credentials page in your Kore.ai workspace.',
    },
    {
      name: 'streamId',
      label: 'Bot / Stream ID',
      type: 'text',
      required: true,
      helpText: 'The botId / streamId shown in App Settings for your SmartAssist bot.',
    },
    {
      name: 'host',
      label: 'API Host (optional)',
      type: 'text',
      required: false,
      helpText: `Override if you use a dedicated or EU instance. Defaults to ${DEFAULT_HOST}.`,
    },
  ]
}

export async function exchangeCredentials(
  fields: Record<string, string>,
): Promise<Credentials> {
  const jwt = fields['jwt']?.trim()
  const accountId = fields['accountId']?.trim()
  const streamId = fields['streamId']?.trim()
  if (!jwt) throw new Error('kore-ai: jwt is required')
  if (!accountId) throw new Error('kore-ai: accountId is required')
  if (!streamId) throw new Error('kore-ai: streamId is required')
  return {
    accessToken: jwt,
    extra: {
      accountId,
      streamId,
      host: fields['host']?.trim() || DEFAULT_HOST,
    },
  }
}
